mapper.select:
select cdr.id as clinicDeptRoomId, ifnull(cdr.dept_room_id, dr.id) as deptRoomId, dr.name as deptRoomName, ifnull(cdr.company_id, cei.company_id) as orgId, cei.abbreviation as orgName, ifnull(cdr.inservice, 1) as inservice from clinic_department_room cdr left join department_room dr on cdr.dept_room_id = dr.id left join clinic_ext_info cei on cdr.company_id = cei.company_id
and cdr.id = #{queryForm.clinicDeptRoomId}
and cdr.company_id = #{queryForm.orgId}
and cdr.dept_room_id = #{queryForm.deptRoomId}
and cdr.inservice = #{queryForm.inservice}
